"""Nonparametric / distribution-free glue: ECDF, Glivenko-Cantelli, bootstrap, KDE."""
from nodespec import N

N("empirical_cdf", "definition", "nonparametric",
  "The empirical CDF of X_1, ..., X_n is F_hat_n(x) = (1/n) sum_{i=1}^n 1{X_i <= x}: the CDF of the empirical distribution P_hat_n that puts mass 1/n at each observation.",
  parseable="F_hat_n(x) = (1/n) sum_{i=1}^n 1{X_i <= x}",
  symbols={"F_hat_n": "the ECDF, a random right-continuous step function", "P_hat_n": "the empirical measure"},
  tcn="A statistic-valued function. For each fixed x, n F_hat_n(x) ~ Binomial(n, F(x)), so E[F_hat_n(x)] = F(x) (unbiased) and Var(F_hat_n(x)) = F(x)(1 - F(x))/n. As a process it is the basis of all distribution-free inference.",
  regime="distribution_free",
  hyps=[],
  proof=("pointwise: n F_hat_n(x) is a sum of iid Bernoulli(F(x)) indicators",
         "prob_bernoulli", "core", None),
  spec=["F_hat_n(x) -> F(x) a.s. pointwise (SLLN) and uniformly (Glivenko-Cantelli)",
        "sqrt(n)(F_hat_n(x) - F(x)) -> N(0, F(x)(1-F(x))) pointwise (CLT), -> a Brownian bridge as a process (Donsker)",
        "the inverse F_hat_n^{-1} gives sample quantiles"],
  cxd={"none_all_hypotheses_essential": "the ECDF is defined for any sample; its consistency (Glivenko-Cantelli) needs only iid -- no moment or smoothness assumption"},
  misuse=["over-interpreting the jagged steps of F_hat_n at small n as features of F",
          "using pointwise CLT bands as if they were simultaneous (they undercover as a band -- use DKW)"],
  apps=["Q-Q plots, P-P plots, and the Kolmogorov-Smirnov / Cramer-von Mises goodness-of-fit tests are all built on F_hat_n",
        "survival analysis: the Kaplan-Meier estimator is the ECDF generalized to censored data"],
  related={"required_by": ["glivenko_cantelli", "dvoretzky_kiefer_wolfowitz", "plug_in_estimator", "bootstrap", "sample_quantile"],
           "uses": ["prob_bernoulli"]},
  sources=["van_der_vaart_asymptotic", "wasserman_all_of_statistics"])

N("order_statistic", "definition", "nonparametric",
  "The order statistics of X_1, ..., X_n are the sorted values X_(1) <= X_(2) <= ... <= X_(n); X_(1) = min, X_(n) = max, and X_((n+1)/2) is the median (n odd).",
  parseable="X_(1) <= X_(2) <= ... <= X_(n),  the sorted sample",
  symbols={"X_(k)": "the k-th smallest observation, type: statistic",
           "the full order statistic": "(X_(1),...,X_(n)) -- always sufficient, and minimal sufficient for a nonparametric family"},
  tcn="A statistic (permutation of the data). For a continuous parent, X_(k) has density n C(n-1, k-1) F(x)^{k-1} (1 - F(x))^{n-k} f(x); F(X_(k)) ~ Beta(k, n - k + 1).",
  regime="distribution_free",
  hyps=[],
  proof=("the event {X_(k) <= x} = {at least k of the X_i are <= x} ~ Binomial(n, F(x)) tail",
         "prob_binomial", "core", None),
  spec=["X_(n) for uniform(0, theta): the sufficient statistic and (after bias correction) the UMVUE of theta",
        "F(X_(k)) ~ Beta(k, n-k+1): distribution-free, the basis of nonparametric quantile confidence intervals",
        "the range X_(n) - X_(1) and the interquartile range are functions of order statistics"],
  cxd={"continuous_parent_for_the_clean_Beta_result": "with ties (discrete data) the Beta-distribution results for F(X_(k)) fail; mid-rank corrections are needed"},
  misuse=["using extreme order statistics (min, max) for inference about the center -- they are driven by the tails and converge at non-standard rates (extreme value theory)",
          "assuming order statistics are independent -- they are strongly dependent (X_(k) <= X_(k+1) always)"],
  related={"required_by": ["sample_quantile"], "uses": ["prob_binomial"]},
  sources=["david_nagaraja_order_statistics", "casella_berger_2e"])

N("sample_quantile", "definition", "nonparametric",
  "The sample p-quantile is F_hat_n^{-1}(p) = inf{ x : F_hat_n(x) >= p }, essentially the order statistic X_(ceil(np)); it is the plug-in estimate of the population quantile Q(p) = F^{-1}(p).",
  parseable="q_hat(p) = F_hat_n^{-1}(p) approx X_( ceil(n p) )",
  symbols={"Q(p) = F^{-1}(p)": "the population quantile being estimated",
           "the sample median": "p = 1/2"},
  tcn="A statistic (an order statistic, up to interpolation convention -- there are ~9 in common use). When F has positive density f(Q(p)) at the quantile, sqrt(n)(q_hat(p) - Q(p)) -> N(0, p(1-p) / f(Q(p))^2).",
  regime="distribution_free",
  hyps=[],
  proof=("Bahadur representation: q_hat(p) = Q(p) + (p - F_hat_n(Q(p))) / f(Q(p)) + o_p(n^{-1/2}); then the CLT for F_hat_n(Q(p))",
         "empirical_cdf", "cited", None),
  spec=["sample median of iid N(mu, sigma^2): sqrt(n)(median - mu) -> N(0, pi sigma^2 / 2) -- asymptotic variance pi/2 times that of Xbar (ARE 2/pi, relative_efficiency)",
        "distribution-free CI for Q(p): [X_(r), X_(s)] with r, s from the Binomial(n, p) quantiles -- exact coverage, no density needed",
        "the sample quantile function traced over p is the Q-Q-plot ordinate"],
  cxd={"positive_density_at_the_quantile": "if f(Q(p)) = 0 (a gap in the support, or estimating an extreme quantile p -> 0) the sqrt(n)-normal limit fails -- the rate and shape change",
       "unique_quantile": "a flat stretch of F at level p makes Q(p) an interval; the sample quantile is unstable there"},
  misuse=["reporting a normal-approximation SE for a sample quantile without a density estimate (the f(Q(p)) in the variance is itself hard to estimate) -- prefer the distribution-free order-statistic interval",
          "estimating a 0.999 quantile from n = 200 observations -- essentially no information in the tail"],
  related={"uses": ["order_statistic", "empirical_cdf"]},
  sources=["van_der_vaart_asymptotic", "hyndman_fan_1996"])

N("glivenko_cantelli", "theorem", "nonparametric",
  "The empirical CDF converges uniformly to the true CDF almost surely: sup_x | F_hat_n(x) - F(x) | -> 0 a.s. as n -> inf, for EVERY distribution F. (The 'fundamental theorem of statistics'.)",
  parseable="sup_x | F_hat_n(x) - F(x) |  -->  0   almost surely,   for every F",
  symbols={"the sup over all x": "uniform, not merely pointwise, convergence -- this is the strengthening over the pointwise SLLN"},
  tcn="An almost-sure uniform-convergence statement, distribution-free. Proof: pointwise SLLN at a fixed grid of quantile levels, monotonicity of F and F_hat_n to fill in between grid points, then let the grid refine. It is the archetype of a 'uniform law of large numbers' over a class of sets (here, half-lines).",
  regime="distribution_free",
  hyps=[],
  proof=("pointwise SLLN at finitely many quantiles + monotonicity sandwiching to control the sup between them; refine the partition",
         "prob_slln", "cited",
         "CITED -- Glivenko 1933, Cantelli 1933; van der Vaart Thm 19.1. The monotonicity-sandwich reduction to finitely many pointwise SLLNs is the elementary content."),
  spec=["justifies the plug-in principle: T(F_hat_n) -> T(F) for any sup-norm-continuous functional T",
        "the basis of the bootstrap's first-order validity (resampling from F_hat_n approximates resampling from F)",
        "generalizes to VC classes (Vapnik-Chervonenkis): uniform convergence over any class of sets with finite VC dimension -- the foundation of statistical learning theory"],
  cxd={"iid": "for dependent data (a time series) F_hat_n still converges pointwise under ergodicity but the uniform / rate results need mixing conditions",
       "the_class_is_not_too_rich": "uniform convergence FAILS over an arbitrary class of sets -- e.g. over all finite sets, sup |P_hat_n(A) - P(A)| = 1 always (A = the sample). Half-lines (VC dim 1) are simple enough; this is why VC dimension matters."},
  misuse=["invoking 'Glivenko-Cantelli' to claim uniform convergence of the empirical measure over a class richer than a Donsker/VC class",
          "assuming it gives a RATE -- it is a qualitative a.s. statement; DKW gives the rate"],
  apps=["the theoretical license for the entire bootstrap and for empirical risk minimization in machine learning (uniform convergence of training error to test error over the hypothesis class)",
        "M-estimation consistency proofs (uniform LLN for the criterion function) are Glivenko-Cantelli over a function class"],
  related={"required_by": ["bootstrap_consistency", "donsker_theorem"], "strengthened_by": ["dvoretzky_kiefer_wolfowitz", "donsker_theorem"],
           "uses": ["empirical_cdf", "prob_slln"]},
  sources=["glivenko_1933", "van_der_vaart_asymptotic", "vapnik_statistical_learning_theory"])

N("dvoretzky_kiefer_wolfowitz", "theorem", "nonparametric",
  "The DKW inequality: P( sup_x | F_hat_n(x) - F(x) | > t ) <= 2 exp(-2 n t^2) for every t > 0 and every F (Massart's tight constant 2). Hence [F_hat_n(x) +- eps_n] with eps_n = sqrt( log(2/alpha) / (2n) ) is a simultaneous 1 - alpha confidence band for the whole CDF.",
  parseable="P( sup_x | F_hat_n(x) - F(x) | > t )  <=  2 exp(-2 n t^2)",
  symbols={"eps_n = sqrt( log(2/alpha) / (2n) )": "the half-width of the distribution-free simultaneous band",
           "the bound is uniform in F": "distribution-free and finite-sample -- no asymptotics"},
  tcn="A finite-sample, distribution-free concentration inequality for the sup-distance -- the quantitative (rate) form of Glivenko-Cantelli. It gives an honest confidence BAND for F, unlike pointwise CLT intervals.",
  regime="distribution_free",
  hyps=[],
  proof=("reduction to a one-sided bound via a reflection/peeling argument, then a Hoeffding-type bound on the maximal deviation; Massart 1990 for the sharp constant 2",
         "prob_hoeffding", "cited",
         "CITED -- Dvoretzky-Kiefer-Wolfowitz 1956; Massart 1990 (tight constant). The connection to Hoeffding's bound on each F_hat_n(x) - F(x) is the entry point."),
  spec=["n = 100, alpha = 0.05: eps_n approx 0.136 -- a band +-0.136 around F_hat_n contains the entire true F with 95% confidence",
        "gives a conservative distribution-free Kolmogorov-Smirnov critical value (the exact KS null is slightly tighter)",
        "sample size for a band of half-width eps: n = log(2/alpha) / (2 eps^2)"],
  cxd={"iid": "for dependent data the exponential rate degrades; block or spectral corrections are needed",
       "the_2_constant": "the pre-Massart bound had a larger constant; using exp(-2nt^2) without the factor 2 in front slightly undercovers for the two-sided band"},
  misuse=["using pointwise +-1.96 sqrt(F_hat(1-F_hat)/n) intervals and drawing them as a band -- that band undercovers substantially",
          "forgetting the band is for F itself, not for future observations (that would be a tolerance interval)"],
  apps=["honest confidence bands for CDFs and survival curves; distribution-free two-sample comparison",
        "off-policy evaluation in reinforcement learning uses DKW-style bounds on the CDF of returns"],
  related={"strengthens": ["glivenko_cantelli"], "uses": ["prob_hoeffding", "empirical_cdf"]},
  sources=["dkw_1956", "massart_1990"])

N("plug_in_estimator", "definition", "nonparametric",
  "The plug-in estimator of a statistical functional theta = T(P) is theta_hat = T(P_hat_n), obtained by applying the functional to the empirical distribution.",
  parseable="theta_hat = T( P_hat_n )   for  theta = T(P)",
  symbols={"T": "the functional (mean, variance, quantile, correlation, a treatment-effect contrast, ...)",
           "influence function IF(x)": "the Gateaux derivative of T at P -- governs the asymptotic variance E[IF^2] and the bias"},
  tcn="A construction. For a Hadamard-differentiable T, sqrt(n)(T(P_hat_n) - T(P)) -> N(0, E[IF(X)^2]) by the functional delta method, and E[IF^2]/n is the asymptotic variance (estimated by plugging in, or by the bootstrap / jackknife).",
  regime="distribution_free",
  hyps=[],
  proof=("functional delta method: T(P_hat_n) = T(P) + (1/n) sum IF(X_i) + o_p(n^{-1/2}); CLT on the average of the influence-function terms",
         "glivenko_cantelli", "cited", None),
  spec=["T(P) = E_P[X] => plug-in Xbar, IF(x) = x - mu",
        "T(P) = Var_P(X) => plug-in the /n sample variance, IF(x) = (x - mu)^2 - sigma^2",
        "T(P) = median => plug-in sample median, IF(x) = (1/2 - 1{x <= m}) / f(m) -- note the density in the denominator"],
  cxd={"Hadamard_differentiability": "T(P) = f_P(x_0) (a density value) or T(P) = number of modes: not a differentiable functional; the plug-in either does not exist (density of a discrete P_hat_n) or converges at a slower nonparametric rate",
       "IF_has_finite_variance": "if E[IF(X)^2] = inf (heavy tails and a functional sensitive to them) the sqrt(n) normal limit fails"},
  misuse=["reporting the naive plug-in SE for a functional with an influence function that involves an unknown density (quantiles) -- use the bootstrap",
          "assuming every functional plugs in at sqrt(n) rate"],
  related={"uses": ["plug_in_principle", "empirical_cdf"], "required_by": ["bootstrap"]},
  sources=["van_der_vaart_asymptotic", "hampel_robust_statistics"])

N("bootstrap", "algorithm", "nonparametric",
  "The (nonparametric) bootstrap approximates the sampling distribution of a statistic T_n = T(X_1,...,X_n) by the distribution of T_n* = T(X_1*, ..., X_n*), where X_1*, ..., X_n* are drawn iid from the empirical distribution P_hat_n (i.e. resampled with replacement from the data); this is estimated by Monte Carlo over B resamples.",
  parseable="approx  law( T_n - theta )   by   law( T_n* - T_n | X_1..X_n ),   X_i* iid ~ P_hat_n",
  symbols={"T_n*": "the statistic recomputed on a resample", "B": "the number of Monte Carlo resamples (500-10000 typically)",
           "the plug-in idea": "replace the unknown P by P_hat_n in 'the sampling distribution of T under P'"},
  tcn="A resampling algorithm. Two error sources: the statistical approximation (P_hat_n for P) and the Monte Carlo approximation (B < inf). It works when T is a smooth functional of P (Hadamard-differentiable); it FAILS for non-smooth functionals (the max, a parameter on a boundary) and for statistics whose limit law depends on unknown nuisance parameters.",
  regime="distribution_free",
  hyps=[],
  proof=("bootstrap_consistency (below): for Hadamard-differentiable T, the conditional law of sqrt(n)(T_n* - T_n) converges to the same limit as sqrt(n)(T_n - theta)",
         "bootstrap_consistency", "cited", None),
  spec=["bootstrap SE: the sample standard deviation of the B values T_n*",
        "percentile CI: the alpha/2 and 1 - alpha/2 empirical quantiles of the T_n* -- simple but first-order; BCa and bootstrap-t are second-order accurate",
        "the parametric bootstrap resamples from F(.; theta_hat) instead of P_hat_n -- useful when a model is trusted"],
  cxd={"smooth_functional": "the maximum of a uniform(0, theta) sample: the bootstrap distribution of n(theta_hat - theta_hat*) does NOT converge to the true Exponential limit -- P(X_(n)* = X_(n)) -> 1 - 1/e, an atom that should not be there. The m-out-of-n bootstrap or subsampling fixes it.",
       "limit_free_of_nuisance": "bootstrapping a non-studentized statistic when the limit variance is unknown gives poor coverage -- bootstrap the STUDENTIZED (pivotal) statistic (bootstrap-t)"},
  misuse=["percentile bootstrap CIs for a skewed statistic at small n (undercover) -- use BCa or bootstrap-t",
          "bootstrapping time-series or clustered data by resampling individual observations (destroys the dependence) -- use the block / cluster bootstrap",
          "too few resamples B for a tail quantile (B = 200 for a 95% CI endpoint is marginal)"],
  apps=["standard errors and CIs for statistics with no closed-form variance: medians, ratios, correlations, indirect effects in mediation analysis, complex survey estimators",
        "random forests and bagging ARE the bootstrap applied to prediction; out-of-bag error is a bootstrap cross-validation"],
  related={"uses": ["plug_in_estimator", "empirical_cdf"], "required_by": ["bootstrap_consistency"],
           "historically_precedes": []},
  sources=["efron_1979", "efron_tibshirani_bootstrap", "davison_hinkley_bootstrap"])

N("bootstrap_consistency", "theorem", "nonparametric",
  "If T(.) is Hadamard-differentiable at P (tangentially to a suitable set) with nondegenerate influence function, then conditionally on the data the bootstrap distribution of sqrt(n)(T(P_hat_n*) - T(P_hat_n)) converges (in probability, in a metric for weak convergence) to the same limit N(0, E[IF^2]) as sqrt(n)(T(P_hat_n) - T(P)). Hence bootstrap SEs and studentized-bootstrap CIs are asymptotically valid.",
  parseable="T Hadamard-diff at P   =>   sup_x | P*( sqrt(n)(T_n* - T_n) <= x ) - P( sqrt(n)(T_n - theta) <= x ) |  -->^p  0",
  symbols={"P*": "probability over the resampling, conditional on X_1..X_n", "IF": "the influence function of T at P"},
  tcn="An asymptotic conditional-convergence statement -- the theoretical justification for the bootstrap. The functional delta method for the bootstrap (van der Vaart-Wellner). For the SAMPLE MEAN and smooth functions of means it holds under a finite second moment.",
  regime="asymptotic",
  hyps=[],
  proof=("functional delta method for the bootstrap empirical process (van der Vaart-Wellner Thm 3.6.1): the bootstrapped empirical process converges conditionally to the same Gaussian limit as the empirical process (Donsker), then apply the Hadamard derivative",
         "glivenko_cantelli", "cited",
         "CITED -- Bickel-Freedman 1981 (the mean); van der Vaart-Wellner 1996 Ch. 3.6 (general). Not formalized."),
  spec=["smooth functions of sample moments (correlation, R^2, ratio of means): bootstrap-consistent under moment conditions",
        "the bootstrap-t (studentized) interval has coverage 1 - alpha + O(1/n) -- one order better than the normal approximation's O(1/sqrt n)",
        "empirical-process functionals (KS statistic, Cramer-von Mises): bootstrap-consistent (Donsker class)"],
  cxd={"Hadamard_differentiability": "the sample maximum / extreme quantiles (not differentiable), a parameter on the boundary of the space, the number of components in a mixture -- the ordinary n-out-of-n bootstrap is INCONSISTENT; subsampling or m-out-of-n is needed",
       "nondegenerate_influence_function": "at a point where IF = 0 (e.g. g(theta_hat) with g'(theta) = 0) the sqrt(n) scaling is wrong and the bootstrap distribution degenerates",
       "iid": "the ordinary bootstrap is inconsistent for dependent data -- block bootstrap under mixing"},
  misuse=["assuming the bootstrap 'always works' -- it has well-catalogued failure cases (Bickel-Gotze-van Zwet 1997)",
          "using the ordinary bootstrap for the max, for superefficient estimators, or on the boundary"],
  related={"uses": ["glivenko_cantelli", "prob_conv_d"], "required_by": []},
  sources=["bickel_freedman_1981", "van_der_vaart_wellner", "bickel_gotze_vanzwet_1997"])

N("kernel_density_estimator", "definition", "nonparametric",
  "The kernel density estimator of f from X_1, ..., X_n is f_hat_h(x) = (1/(n h)) sum_{i=1}^n K( (x - X_i) / h ), where K is a kernel (a symmetric density, e.g. Gaussian or Epanechnikov) and h > 0 is the bandwidth.",
  parseable="f_hat_h(x) = (n h)^{-1} sum_{i=1}^n K( (x - X_i)/h )",
  symbols={"K": "the kernel, type: symmetric probability density with int u^2 K(u) du = kappa_2 < inf",
           "h": "the bandwidth / smoothing parameter -- the crucial tuning knob",
           "f_hat_h": "a genuine density (integrates to 1) if K is"},
  tcn="A statistic-valued function; a smoothed version of the empirical measure. It is biased for f (unlike the ECDF for F) -- density estimation is genuinely nonparametric, with a bias-variance tradeoff controlled by h (kde_bias_variance_tradeoff).",
  regime="distribution_free",
  hyps=[],
  proof=("E[f_hat_h(x)] = (K_h * f)(x), a convolution smoothing of f; Var[f_hat_h(x)] = (n h)^{-1} f(x) R(K) + O(1/n)",
         "kde_bias_variance_tradeoff", "core", None),
  spec=["h -> 0 with n h -> inf: f_hat_h(x) -> f(x) in probability at each continuity point",
        "the choice of K barely matters (efficiency within a few %); the choice of h matters enormously",
        "multivariate KDE suffers the curse of dimensionality -- the rate degrades to n^{-2/(4+d)}"],
  cxd={"h_chosen_well": "h too small: f_hat is a spiky mess (n bumps); h too large: f_hat is oversmoothed and hides real features (bimodality). There is no h that is right everywhere if f has varying curvature -- adaptive bandwidths address this.",
       "f_smooth": "if f has a discontinuity or a kink (uniform density's edges, an exponential at 0) the KDE smears it and the bias there is O(1), not O(h^2) -- boundary bias"},
  misuse=["using the default bandwidth (often Silverman's rule, optimal only for near-Gaussian f) on a clearly multimodal or skewed sample",
          "reading small wiggles in a KDE as real structure",
          "KDE near a hard boundary (nonnegative data at 0) without a boundary correction"],
  apps=["exploratory data visualization (the smooth alternative to a histogram); the violin plot is a KDE",
        "naive Bayes classifiers with continuous features; density-ratio estimation; the Parzen-window classifier"],
  related={"required_by": ["kde_bias_variance_tradeoff"], "uses": ["prob_pdf"]},
  sources=["silverman_density_estimation", "wand_jones_kernel_smoothing", "tsybakov_nonparametric"])

N("kde_bias_variance_tradeoff", "regime", "nonparametric",
  "For a KDE with a second-order kernel and twice-differentiable f, at a fixed x: bias(f_hat_h(x)) approx (h^2 / 2) kappa_2 f''(x) and Var(f_hat_h(x)) approx (n h)^{-1} R(K) f(x). The mean integrated squared error is minimized at h* proportional to n^{-1/5}, giving MISE = O(n^{-4/5}) -- strictly slower than the parametric n^{-1}.",
  parseable="bias = O(h^2),  var = O(1/(n h))   =>   h* ~ n^{-1/5},   MISE(f_hat_{h*}) ~ n^{-4/5}",
  symbols={"kappa_2 = int u^2 K(u) du": "the kernel's second moment", "R(K) = int K(u)^2 du": "the kernel roughness",
           "h* = ( R(K) / (kappa_2^2 int f''^2) )^{1/5} n^{-1/5}": "the MISE-optimal bandwidth"},
  tcn="An asymptotic rate statement -- the canonical nonparametric bias-variance tradeoff. Balancing h^4 (squared bias) against 1/(nh) (variance) gives h ~ n^{-1/5}. The n^{-4/5} rate is minimax-optimal over the class of twice-differentiable densities (matches the lower bound, minimax_rate).",
  regime="asymptotic",
  hyps=[],
  proof=("Taylor-expand E[f_hat_h(x)] = int K(u) f(x - hu) du = f(x) + (h^2/2) kappa_2 f''(x) + o(h^2); the variance is a direct computation; minimize AMISE(h) = (h^4/4) kappa_2^2 int f''^2 + R(K)/(nh)",
         "ra_taylor_theorem", "core",
         "validation/proof-checks.lean Stat.kde_amise_optimal_h -- minimizing a h^4 + b/(nh) over h gives h ~ (b/(4an))^{1/5}, and the minimized value ~ n^{-4/5} (the exponent arithmetic)"),
  spec=["the same 2nd-order-vs-4th-order rate logic governs local polynomial regression, spline smoothing, and every nonparametric-regression method",
        "higher-order kernels (allowing negative lobes) push the bias to O(h^4) and the rate to n^{-8/9} -- at the cost of a possibly-negative density estimate",
        "d dimensions: h ~ n^{-1/(4+d)}, MISE ~ n^{-4/(4+d)} -- the curse of dimensionality"],
  cxd={"f_twice_differentiable": "if f is only Lipschitz (one derivative) the best rate drops to n^{-2/3}; if f has a jump, to n^{-1/2} away from the jump and O(1) at it",
       "interior_x": "at the boundary of the support the bias is O(h) not O(h^2) unless a boundary kernel is used -- boundary bias dominates the MISE if untreated"},
  misuse=["expecting parametric-rate (n^{-1/2}) confidence-interval width from a density estimate",
          "plugging an estimate of int f''^2 into h* and ignoring that this is itself a harder problem (needs a pilot bandwidth)",
          "comparing KDEs at the same h across samples of very different size"],
  apps=["the theoretical reason nonparametric methods 'need a lot of data' -- and the basis for choosing between a parametric model (fast rate, risk of bias) and a nonparametric one (slow rate, flexible)",
        "cross-validation bandwidth selection targets exactly this MISE"],
  related={"uses": ["ra_taylor_theorem", "mse_bias_variance_decomposition"], "required_by": ["minimax_rate"]},
  sources=["silverman_density_estimation", "tsybakov_nonparametric", "wand_jones_kernel_smoothing"])
